// The #442 shape in a package: `Space` is not exported, and `Conn`, which is,
// hands one out. An importer of `Conn` holds `Space` values without naming the
// class, so it may call their methods too, and each method it calls must be
// in the final link: `hidden`, rather than the `internal` a private method is.

class Space {
  sent: i32;
  label: string;

  constructor(sent: i32, label: string) {
    this.sent = sent;
    this.label = label;
  }

  unsent(total: i32): i32 {
    return total - this.sent;
  }

  name(): string {
    return `space ${this.label}`;
  }

  // A small `Result` travels as `{ i1, i32, i32 }` between private functions
  // and as one `i64` otherwise: the importer's call and this `define` must pick
  // the same one.
  take(n: i32): Result<i32, i32> {
    if (n > this.sent) {
      return Err(n - this.sent);
    }
    return Ok(this.sent - n);
  }

  // A generic method: its instantiation is made here, in the template's own
  // module, and called from the importer.
  either<T>(low: T, high: T): T {
    return this.sent > 5 ? high : low;
  }

  // Called only from this module, so it stays `internal`.
  twice(): i32 {
    return this.sent * 2;
  }
}

export class Conn {
  initial: Space;
  handshake: Space;

  constructor() {
    this.initial = new Space(3, "initial");
    this.handshake = new Space(10, "handshake");
  }

  space(level: i32): Space {
    return level === 0 ? this.initial : this.handshake;
  }

  weight(): i32 {
    return this.initial.twice() + this.handshake.twice();
  }
}
